{
  "items": [
    {
      "name": "Matrix.det_le",
      "module_name": "Mathlib.LinearAlgebra.Matrix.AbsoluteValue",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} {S : Type u_2} [inst : CommRing R] [Nontrivial R] [inst_2 : CommRing S] [inst_3 : LinearOrder S]\n  [IsStrictOrderedRing S] {n : Type u_3} [inst_5 : Fintype n] [inst_6 : DecidableEq n] {A : Matrix n n R}\n  {abv : AbsoluteValue R S} {x : S},\n  (∀ (i j : n), abv (A i j) ≤ x) → abv A.det ≤ (Fintype.card n).factorial • x ^ Fintype.card n"
    },
    {
      "name": "MvPowerSeries.weightedOrder",
      "module_name": "Mathlib.RingTheory.MvPowerSeries.Order",
      "kind": "definition",
      "type": "{σ : Type u_1} → {R : Type u_2} → [Semiring R] → (σ → ℕ) → MvPowerSeries σ R → ℕ∞"
    },
    {
      "name": "MvPowerSeries.weightedOrder_mul_ge",
      "module_name": "Mathlib.RingTheory.MvPowerSeries.Order",
      "kind": "theorem",
      "type": "∀ {σ : Type u_1} {R : Type u_2} [inst : Semiring R] (w : σ → ℕ) {f g : MvPowerSeries σ R},\n  MvPowerSeries.weightedOrder w f + MvPowerSeries.weightedOrder w g ≤ MvPowerSeries.weightedOrder w (f * g)"
    },
    {
      "name": "Matrix.abs_det_reindex",
      "module_name": "Mathlib.LinearAlgebra.Matrix.Determinant.Basic",
      "kind": "theorem",
      "type": "∀ {m : Type u_1} {n : Type u_2} [inst : DecidableEq n] [inst_1 : Fintype n] [inst_2 : DecidableEq m]\n  [inst_3 : Fintype m] {R : Type u_3} [inst_4 : CommRing R] [inst_5 : LinearOrder R] [IsStrictOrderedRing R]\n  (e₁ e₂ : m ≃ n) (A : Matrix m m R), |((Matrix.reindex e₁ e₂) A).det| = |A.det|"
    },
    {
      "name": "Matrix.detp",
      "module_name": "Mathlib.LinearAlgebra.Matrix.SemiringInverse",
      "kind": "definition",
      "type": "{n : Type u_1} → {R : Type u_3} → [Fintype n] → [DecidableEq n] → [CommSemiring R] → ℤˣ → Matrix n n R → R"
    },
    {
      "name": "MvPowerSeries.weightedOrder_mul",
      "module_name": "Mathlib.RingTheory.MvPowerSeries.NoZeroDivisors",
      "kind": "theorem",
      "type": "∀ {σ : Type u_1} {R : Type u_2} [inst : Semiring R] [NoZeroDivisors R] (w : σ → ℕ) (f g : MvPowerSeries σ R),\n  MvPowerSeries.weightedOrder w (f * g) = MvPowerSeries.weightedOrder w f + MvPowerSeries.weightedOrder w g"
    }
  ]
